package com.farm2market.controller;
import com.farm2market.entity.*; import com.farm2market.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/farmers/me") public class FarmerController {final UserRepository users;final ProductRepository products;final OrderRepository orders;FarmerController(UserRepository u,ProductRepository p,OrderRepository o){users=u;products=p;orders=o;} @GetMapping public User me(@RequestParam String email){return users.findByEmail(email).orElseThrow();} @GetMapping("/products") public List<Product> ps(@RequestParam String email){return products.findByFarmer(users.findByEmail(email).orElseThrow());} @GetMapping("/orders") public List<Order> os(@RequestParam String email){return orders.findByFarmerOrderByCreatedAtDesc(users.findByEmail(email).orElseThrow());}}
